[
  {
    "severity": "P1明显",
    "category": "style-deviation",
    "description": "卡片区域状态数字使用了工业蓝（34项）和功能绿（35项），与“酱园琥珀”设计语言要求的酱色（深棕红）+ 琥珀点缀冲突，破坏了整体温润的调性。",
    "suggestion": "将功能状态色替换为琥珀色系的明度变化或酱红色系的补色，避免直接使用高饱和度的系统蓝绿。"
  },
  {
    "severity": "P1明显",
    "category": "contrast",
    "description": "首个卡片“0项 待处理”使用了低对比度灰字，在暗色背景下几乎不可见，不符合可访问性标准。",
    "suggestion": "提升禁用/零状态文字的亮度，或使用琥珀色的低透明度版本以维持视觉层级。"
  },
  {
    "severity": "P2瑕疵",
    "category": "ua-default-style",
    "description": "搜索框（搜索会话 / AI 同事）的内阴影和边框质感带有浏览器默认 input 控件残留感，与“圆角卡片、轻量阴影”的酱园语言不符。",
    "suggestion": "移除内阴影，改用扁平色块背景加微弱的酱色描边，或使用琥珀色呼吸光做聚焦态。"
  },
  {
    "severity": "P2瑕疵",
    "category": "spacing",
    "description": "“最近对话”下方的消息条目卡片内边距失衡，头像距离左侧边缘过近，且文字与头像间距过窄。",
    "suggestion": "增加卡片内边距（建议 12px-16px），并增大头像与文本间的水平间距。"
  },
  {
    "severity": "P1明显",
    "category": "dark-mode-flaws",
    "description": "暗色模式背景为纯黑灰色，未体现“暖纸底”在深色下的质感，导致页面整体呈现标准的工业科技感而非品牌特有的文化感。",
    "suggestion": "为深色背景加入极低饱和度的酱红色（深棕红）底色，模拟深色宣纸或酱池的视觉深度。"
  },
  {
    "severity": "P2瑕疵",
    "category": "inconsistency",
    "description": "顶部“鲜酿”印章元素使用了衬线体，而下方的数字和按钮文本使用了标准的非衬线系统字体，字体视觉节奏断层。",
    "suggestion": "关键数字（如 34, 35）可尝试使用更具设计感的定制字体，或在标题位保持字体的品牌感统一。"
  },
  {
    "severity": "P2瑕疵",
    "category": "layout-overflow",
    "description": "“AI 同事”列表下方的卡片容器边缘过于锋利（直角感），在圆角卡片为主的界面中显得突兀。",
    "suggestion": "统一所有容器圆角（建议 8px-12px），保持视觉语言连贯性。"
  },
  {
    "severity": "P0毁容级",
    "category": "ua-default-style",
    "description": "底部“帮我登记一条采购单”区域疑似残留了原生 button 的聚焦框或默认灰边框，表现为一圈生硬的细线。",
    "suggestion": "设置 outline: none 并自定义 border 样式，确保符合“酱园”温润的视觉规范。"
  }
]
